{"content": "import click


def test_option_help_is_none(runner):
    @click.command()
    @click.option("--name", help=None)
    def cli(name):
        click.echo(name)

    result = runner.invoke(cli, ["--name", "test"])
    assert result.exception is None
    assert result.output.strip() == "test"


def test_option_cls_is_none(runner):
    @click.command()
    @click.option("--name", cls=None)
    def cli(name):
        click.echo(name)

    result = runner.invoke(cli, ["--name", "test"])
    assert result.exception is None
    assert result.output.strip() == "test"


def test_argument_cls_is_none(runner):
    @click.command()
    @click.argument("name", cls=None)
    def cli(name):
        click.echo(name)

    result = runner.invoke(cli, ["test"])
    assert result.exception is None
    assert result.output.strip() == "test"


def test_group_cls_is_none(runner):
    @click.group(cls=None)
    def cli():
        pass

    @cli.command()
    def sub():
        click.echo("sub")

    result = runner.invoke(cli, ["sub"])
    assert result.exception is None
